@sig trait TransferReportDerivation_Api {
  def id: Art.BridgeId
  def resolution_Id : Art.PortId
  def supervisorStatus_Id : Art.PortId
  def verificationFinding_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var supervisorStatus: Mining_Cargo_Transfer_Supervisor.TransferSupervisorStatus.Type = $

  def put_supervisorStatus(value : Mining_Cargo_Transfer_Supervisor.TransferSupervisorStatus.Type) : Unit = {
    Contract(
      Modifies(supervisorStatus),
      Ensures(
        supervisorStatus == value
      )
    )
    Spec {
      supervisorStatus = value
    }

    Art.putValue(supervisorStatus_Id, Mining_Cargo_Transfer_Supervisor.TransferSupervisorStatus_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var verificationFinding: Mining_Cargo_Transfer_Supervisor.TransferVerificationFinding.Type = $

  def put_verificationFinding(value : Mining_Cargo_Transfer_Supervisor.TransferVerificationFinding.Type) : Unit = {
    Contract(
      Modifies(verificationFinding),
      Ensures(
        verificationFinding == value
      )
    )
    Spec {
      verificationFinding = value
    }

    Art.putValue(verificationFinding_Id, Mining_Cargo_Transfer_Supervisor.TransferVerificationFinding_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class TransferReportDerivation_Initialization_Api (
  val id: Art.BridgeId,
  val resolution_Id : Art.PortId,
  val supervisorStatus_Id : Art.PortId,
  val verificationFinding_Id : Art.PortId) extends TransferReportDerivation_Api

@datatype class TransferReportDerivation_Operational_Api (
  val id: Art.BridgeId,
  val resolution_Id : Art.PortId,
  val supervisorStatus_Id : Art.PortId,
  val verificationFinding_Id : Art.PortId) extends TransferReportDerivation_Api {

  // Logika spec var representing port state for incoming data port
  @spec var resolution: Mining_Cargo_Transfer_Supervisor.TransferResolution = $

  def get_resolution() : Option[Mining_Cargo_Transfer_Supervisor.TransferResolution] = {
    Contract(
      Ensures(
        Res == Some(resolution)
      )
    )
    val value : Option[Mining_Cargo_Transfer_Supervisor.TransferResolution] = Art.getValue(resolution_Id) match {
      case Some(Mining_Cargo_Transfer_Supervisor.TransferResolution_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port resolution.  Expecting 'Mining_Cargo_Transfer_Supervisor.TransferResolution_Payload' but received ${v}")
        None[Mining_Cargo_Transfer_Supervisor.TransferResolution]()
      case _ => None[Mining_Cargo_Transfer_Supervisor.TransferResolution]()
    }
    return value
  }
}
